import java.util.Arrays;

public class SegmentTreeTour {
    static int n;
    static long[] tree;

    static void build(int[] a, int node, int lo, int hi) {
        if (lo == hi) { tree[node] = a[lo]; return; }
        int mid = (lo + hi) / 2;
        build(a, 2 * node + 1, lo, mid);
        build(a, 2 * node + 2, mid + 1, hi);
        tree[node] = tree[2 * node + 1] + tree[2 * node + 2];
    }

    static long query(int node, int lo, int hi, int l, int r) {
        if (r < lo || hi < l) return 0;                       // no overlap
        if (l <= lo && hi <= r) return tree[node];            // total overlap
        int mid = (lo + hi) / 2;                              // partial: ask both children
        return query(2 * node + 1, lo, mid, l, r) + query(2 * node + 2, mid + 1, hi, l, r);
    }

    static void update(int node, int lo, int hi, int i, int value) {
        if (lo == hi) { tree[node] = value; return; }
        int mid = (lo + hi) / 2;
        if (i <= mid) update(2 * node + 1, lo, mid, i, value);
        else update(2 * node + 2, mid + 1, hi, i, value);
        tree[node] = tree[2 * node + 1] + tree[2 * node + 2];   // fix sums on the way up
    }

    public static void main(String[] args) {
        int[] sales = {5, 8, 6, 3, 2, 7, 2, 6};
        n = sales.length;
        tree = new long[4 * n];
        build(sales, 0, 0, n - 1);
        System.out.println("daily sales: " + Arrays.toString(sales));
        System.out.println("sum of days 2..6 = " + query(0, 0, n - 1, 2, 6));
        System.out.println("sum of all days  = " + query(0, 0, n - 1, 0, n - 1));
        update(0, 0, n - 1, 3, 10);                            // day 3 corrected from 3 to 10
        System.out.println("after setting day 3 to 10: days 2..6 = " + query(0, 0, n - 1, 2, 6));
    }
}

public class RangeQueries {
    static int[] a = {5, 8, 6, 3, 2, 7, 2, 6};
    static int n = a.length;
    static int[] tree = new int[4 * n];
    static int visited;

    static void build(int node, int lo, int hi) {
        if (lo == hi) { tree[node] = a[lo]; return; }
        int mid = (lo + hi) / 2;
        build(2 * node + 1, lo, mid);
        build(2 * node + 2, mid + 1, hi);
        tree[node] = tree[2 * node + 1] + tree[2 * node + 2];
    }

    static int query(int node, int lo, int hi, int l, int r, int depth, boolean trace) {
        visited++;
        String where = "  ".repeat(depth) + "[" + lo + "," + hi + "] ";
        if (r < lo || hi < l) {
            if (trace) System.out.println(where + "no overlap -> 0");
            return 0;
        }
        if (l <= lo && hi <= r) {
            if (trace) System.out.println(where + "total overlap -> " + tree[node]);
            return tree[node];
        }
        if (trace) System.out.println(where + "partial overlap -> ask children");
        int mid = (lo + hi) / 2;
        return query(2 * node + 1, lo, mid, l, r, depth + 1, trace) + query(2 * node + 2, mid + 1, hi, l, r, depth + 1, trace);
    }

    public static void main(String[] args) {
        build(0, 0, n - 1);
        System.out.println("root sum " + tree[0] + ", children " + tree[1] + " and " + tree[2]);
        System.out.println("query sum of [2, 6]:");
        System.out.println("= " + query(0, 0, n - 1, 2, 6, 0, true));

        int worst = 0;
        for (int l = 0; l < n; l++)
            for (int r = l; r < n; r++) {
                visited = 0;
                query(0, 0, n - 1, l, r, 0, false);
                worst = Math.max(worst, visited);
            }
        System.out.println("most nodes visited by any of the 36 ranges: " + worst + " (of " + (2 * n - 1) + " nodes)");
    }
}

public class LazyPropagation {
    static int n = 8;
    static long[] tree = new long[4 * n], lazy = new long[4 * n];

    static void apply(int node, int lo, int hi, long v) {
        tree[node] += v * (hi - lo + 1);       // every element in [lo, hi] grows by v
        lazy[node] += v;                       // children still owe v
    }

    static void push(int node, int lo, int hi) {
        if (lazy[node] == 0) return;
        int mid = (lo + hi) / 2;
        System.out.println("    push +" + lazy[node] + " from [" + lo + "," + hi + "] to its children");
        apply(2 * node + 1, lo, mid, lazy[node]);
        apply(2 * node + 2, mid + 1, hi, lazy[node]);
        lazy[node] = 0;
    }

    static void add(int node, int lo, int hi, int l, int r, long v) {
        if (r < lo || hi < l) return;
        if (l <= lo && hi <= r) {
            apply(node, lo, hi, v);
            System.out.println("    note +" + v + " on [" + lo + "," + hi + "]");
            return;
        }
        push(node, lo, hi);                    // before going deeper
        int mid = (lo + hi) / 2;
        add(2 * node + 1, lo, mid, l, r, v);
        add(2 * node + 2, mid + 1, hi, l, r, v);
        tree[node] = tree[2 * node + 1] + tree[2 * node + 2];
    }

    static long sum(int node, int lo, int hi, int l, int r) {
        if (r < lo || hi < l) return 0;
        if (l <= lo && hi <= r) return tree[node];
        push(node, lo, hi);
        int mid = (lo + hi) / 2;
        return sum(2 * node + 1, lo, mid, l, r) + sum(2 * node + 2, mid + 1, hi, l, r);
    }

    public static void main(String[] args) {
        long[] plain = new long[n];                  // brute-force referee
        int[][] ops = {{1, 6, 3}, {3, 5, 0}, {4, 7, 10}, {0, 7, 0}, {5, 5, 0}};   // {l, r, add}; add 0 = query
        for (int[] op : ops) {
            int l = op[0], r = op[1];
            if (op[2] != 0) {
                System.out.println("add " + op[2] + " to [" + l + ", " + r + "]");
                add(0, 0, n - 1, l, r, op[2]);
                for (int i = l; i <= r; i++) plain[i] += op[2];
            } else {
                System.out.println("sum of [" + l + ", " + r + "]");
                long fast = sum(0, 0, n - 1, l, r), slow = 0;
                for (int i = l; i <= r; i++) slow += plain[i];
                System.out.println("  = " + fast + (fast == slow ? " (matches the plain array)" : " MISMATCH " + slow));
            }
        }
    }
}

import java.util.Arrays;

public class PointUpdates {
    static int[] a = {7, 4, 6, 8, 5, 3, 9, 2};
    static int n = a.length;
    static int[] tree = new int[4 * n];
    static int reads;

    static void build(int node, int lo, int hi) {
        if (lo == hi) { tree[node] = a[lo]; return; }
        int mid = (lo + hi) / 2;
        build(2 * node + 1, lo, mid);
        build(2 * node + 2, mid + 1, hi);
        tree[node] = Math.min(tree[2 * node + 1], tree[2 * node + 2]);
    }

    static void update(int node, int lo, int hi, int i, int value) {
        if (lo == hi) {
            tree[node] = value;
        } else {
            int mid = (lo + hi) / 2;
            if (i <= mid) update(2 * node + 1, lo, mid, i, value);
            else update(2 * node + 2, mid + 1, hi, i, value);
            tree[node] = Math.min(tree[2 * node + 1], tree[2 * node + 2]);   // recompute on the way up
        }
        System.out.println("    [" + lo + "," + hi + "] min = " + tree[node]);
    }

    static int min(int node, int lo, int hi, int l, int r) {
        reads++;
        if (r < lo || hi < l) return Integer.MAX_VALUE;
        if (l <= lo && hi <= r) return tree[node];
        int mid = (lo + hi) / 2;
        return Math.min(min(2 * node + 1, lo, mid, l, r), min(2 * node + 2, mid + 1, hi, l, r));
    }

    public static void main(String[] args) {
        build(0, 0, n - 1);
        System.out.println("values " + Arrays.toString(a) + ", overall min " + tree[0]);
        int[][] changes = {{5, 1}, {2, 9}};
        for (int[] c : changes) {
            System.out.println("set position " + c[0] + " to " + c[1] + ", path from leaf to root:");
            a[c[0]] = c[1];
            update(0, 0, n - 1, c[0], c[1]);
        }
        reads = 0;
        int m = min(0, 0, n - 1, 1, 6);
        int scan = Integer.MAX_VALUE;
        for (int i = 1; i <= 6; i++) scan = Math.min(scan, a[i]);
        System.out.println("min of [1, 6] = " + m + " (tree read " + reads + " nodes; a scan reads 6 elements and gets " + scan + ")");
    }
}

import java.util.Arrays;

public class RangeUpdates {
    static int n = 7;
    static int[] addOn = new int[4 * n];          // value added to every element of the node's segment

    static void rangeAdd(int node, int lo, int hi, int l, int r, int v) {
        if (r < lo || hi < l) return;
        if (l <= lo && hi <= r) { addOn[node] += v; return; }   // covers the node: store and stop
        int mid = (lo + hi) / 2;
        rangeAdd(2 * node + 1, lo, mid, l, r, v);
        rangeAdd(2 * node + 2, mid + 1, hi, l, r, v);
    }

    static int pointQuery(int i) {                // sum of the additions on the root-to-leaf path
        int node = 0, lo = 0, hi = n - 1, total = 0;
        while (true) {
            total += addOn[node];
            if (lo == hi) return total;
            int mid = (lo + hi) / 2;
            if (i <= mid) { node = 2 * node + 1; hi = mid; }
            else { node = 2 * node + 2; lo = mid + 1; }
        }
    }

    public static void main(String[] args) {
        String[] nights = {"Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"};
        int[][] bookings = {{0, 2, 3}, {1, 4, 2}, {4, 6, 5}, {2, 2, 1}, {5, 6, 4}};   // {first night, last night, rooms}

        int[] naive = new int[n];
        int[] diff = new int[n + 1];
        for (int[] b : bookings) {
            for (int i = b[0]; i <= b[1]; i++) naive[i] += b[2];           // O(length) each
            diff[b[0]] += b[2];                                            // O(1) each
            diff[b[1] + 1] -= b[2];
            rangeAdd(0, 0, n - 1, b[0], b[1], b[2]);                      // O(log n) each
        }
        int[] fromDiff = new int[n];
        int running = 0;
        for (int i = 0; i < n; i++) { running += diff[i]; fromDiff[i] = running; }   // one O(n) pass
        int[] fromTree = new int[n];
        for (int i = 0; i < n; i++) fromTree[i] = pointQuery(i);

        System.out.println("night   naive  diff  tree");
        for (int i = 0; i < n; i++) {
            System.out.printf("%-6s %6d %5d %5d%n", nights[i], naive[i], fromDiff[i], fromTree[i]);
        }
        System.out.println("difference array: " + Arrays.toString(diff));
    }
}
